import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getHistory, getAnalysis } from '../api/client';
import { Eye, Calendar, Briefcase, Terminal, ArrowLeft, Cpu, Sparkles } from 'lucide-react';
import toast from 'react-hot-toast';
import BackgroundEffects from '../components/BackgroundEffects';

const History = () => {
  const [analyses, setAnalyses] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadHistory();
  }, []);

  const loadHistory = async () => {
    try {
      const data = await getHistory();
      setAnalyses(data);
    } catch (error) {
      toast.error('Failed to load analysis history');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleView = async (id) => {
    try {
      const analysis = await getAnalysis(id);
      sessionStorage.setItem('analysisResult', JSON.stringify(analysis));
      navigate('/results');
    } catch (error) {
      toast.error('Failed to load analysis details');
      console.error(error);
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-scifi-900 flex flex-col items-center justify-center relative overflow-hidden">
        <BackgroundEffects />
        <div className="relative z-10 text-center">
          <Cpu className="w-12 h-12 text-scifi-200 animate-pulse mx-auto mb-4" />
          <p className="text-sm font-mono text-scifi-200">Fetching Analysis History Logs...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-scifi-900 pt-8 pb-20 px-4 relative overflow-hidden">
      <BackgroundEffects />

      <div className="max-w-5xl mx-auto relative z-10">

        {/* Top Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4 pb-6 border-b border-scifi-600/20">
          <div>
            <div className="flex items-center space-x-2 mb-1">
              <Terminal className="w-6 h-6 text-scifi-200" />
              <h1 className="text-3xl font-heading font-extrabold text-scifi-100">Analysis History Logs</h1>
            </div>
            <p className="text-xs font-mono text-scifi-200">
              Audit logs of previously evaluated developer resumes
            </p>
          </div>

          <button
            onClick={() => navigate('/')}
            className="flex items-center space-x-2 px-4 py-2 rounded-xl glass-pill text-scifi-200 hover:text-scifi-100 hover:border-scifi-600/50 transition-all font-mono text-xs shrink-0"
          >
            <ArrowLeft className="w-4 h-4 text-scifi-200" />
            <span>Return to Command Center</span>
          </button>
        </div>

        {/* History List */}
        {analyses.length === 0 ? (
          <div className="glass-card rounded-3xl p-12 text-center border border-scifi-600/30">
            <Sparkles className="w-12 h-12 text-scifi-200 mx-auto mb-4 animate-bounce" />
            <p className="text-lg font-heading font-bold text-scifi-100 mb-1">No Past Analyses Logged</p>
            <p className="text-xs font-mono text-scifi-200 mb-6">Upload a resume in the Command Center to record audit history.</p>
            <button
              onClick={() => navigate('/')}
              className="px-6 py-3 rounded-xl bg-scifi-600 hover:bg-scifi-500 text-scifi-100 font-heading font-bold text-sm shadow-purple-glow transition-all"
            >
              Analyze Your First Resume
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {analyses.map((analysis) => (
              <div
                key={analysis.id}
                className="glass-card-hover p-6 rounded-2xl border border-scifi-600/30 flex flex-col sm:flex-row sm:items-center justify-between gap-4"
              >
                <div className="flex-1">
                  <div className="flex items-center space-x-3 mb-2">
                    <div className="p-2 rounded-xl bg-scifi-600/20 border border-scifi-600/40 text-scifi-200">
                      <Briefcase className="w-5 h-5" />
                    </div>
                    <h3 className="font-heading font-bold text-lg text-scifi-100">
                      {analysis.job_title || 'Software Position'}
                    </h3>
                  </div>

                  <div className="flex items-center space-x-4 text-xs font-mono text-scifi-200 ml-1">
                    <div className="flex items-center space-x-1.5">
                      <Calendar className="w-3.5 h-3.5 text-scifi-200" />
                      <span>{formatDate(analysis.created_at)}</span>
                    </div>
                    <span>•</span>
                    <span className="text-scifi-400">ID: #{analysis.id}</span>
                  </div>
                </div>

                <div className="flex items-center justify-between sm:justify-end space-x-6">
                  <div className="text-right">
                    <p className="text-[10px] font-mono uppercase text-scifi-200 mb-0.5">Match Score</p>
                    <span className="px-3 py-1 rounded-full text-base font-heading font-bold border text-scifi-100 border-scifi-600/50 bg-scifi-600/30 shadow-purple-glow">
                      {Math.round(analysis.overall_score || 0)}%
                    </span>
                  </div>

                  <button
                    onClick={() => handleView(analysis.id)}
                    className="flex items-center space-x-2 px-4 py-2.5 rounded-xl bg-scifi-600/30 hover:bg-scifi-600/50 text-scifi-100 border border-scifi-600/50 text-xs font-mono font-bold transition-all shadow-purple-glow"
                  >
                    <Eye className="w-4 h-4 text-scifi-200" />
                    <span>Inspect</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>
    </div>
  );
};

export default History;
